    try:
        p = subprocess.run(cmd + ["-c", prog], capture_output=True, text=True,
                           timeout=10, cwd=cwd, env=env)
        return p.returncode, p.stdout, p.stderr
    except subprocess.TimeoutExpired:
        return None, "", ""

