def V(engine, verdict, kind="", rc=0):
    return conf.Verdict(engine=engine, entry_id="e1", verdict=verdict, kind=kind,
                        detail="", expected_rc=rc, actual_rc=rc)

def er(name, v):
    return conf.EngineReport(engine=name, match=0, unsupported=0, mismatch=0,
                             total=1, coverage=0.0, verdicts=[v])

def report(arms):
    return conf.Report(engines={n: er(n, v) for n, v in arms.items()},
                       routing_errors=[], skipped=[], seconds=0.0,
                       routes={"e1": eng.Route("lypning", "", "")})

